
import { useEffect, useMemo, useRef, useState } from 'react'

type CountrySelectProps = {
  value: string
  onChange: (country: string) => void
}

// ISO 3166-1 country and territory codes.
// Country names are generated by the browser's Intl API.
const COUNTRY_CODES = `
AD AE AF AG AI AL AM AO AQ AR AS AT AU AW AX AZ
BA BB BD BE BF BG BH BI BJ BL BM BN BO BQ BR BS BT BV BW BY BZ
CA CC CD CF CG CH CI CK CL CM CN CO CR CU CV CW CX CY CZ
DE DJ DK DM DO DZ
EC EE EG EH ER ES ET
FI FJ FK FM FO FR
GA GB GD GE GF GG GH GI GL GM GN GP GQ GR GS GT GU GW GY
HK HM HN HR HT HU
ID IE IL IM IN IO IQ IR IS IT
JE JM JO JP
KE KG KH KI KM KN KP KR KW KY KZ
LA LB LC LI LK LR LS LT LU LV LY
MA MC MD ME MF MG MH MK ML MM MN MO MP MQ MR MS MT MU MV MW MX MY MZ
NA NC NE NF NG NI NL NO NP NR NU NZ
OM
PA PE PF PG PH PK PL PM PN PR PS PT PW PY
QA
RE RO RS RU RW
SA SB SC SD SE SG SH SI SJ SK SL SM SN SO SR SS ST SV SX SY SZ
TC TD TF TG TH TJ TK TL TM TN TO TR TT TV TW TZ
UA UG UM US UY UZ
VA VC VE VG VI VN VU
WF WS
YE YT
ZA ZM ZW
`.trim().split(/\s+/)

const displayNames = new Intl.DisplayNames(['en'], {
  type: 'region',
})

const countries = COUNTRY_CODES
  .map(code => ({
    code,
    name: displayNames.of(code) || code,
  }))
  .sort((a, b) => a.name.localeCompare(b.name))

// City names and common alternative names map to countries.
// Add more aliases here whenever needed.
const cityAliases = [
  { city: 'Dubai', countryCode: 'AE' },
  { city: 'Abu Dhabi', countryCode: 'AE' },
  { city: 'Sharjah', countryCode: 'AE' },
  { city: 'Ajman', countryCode: 'AE' },
  { city: 'Doha', countryCode: 'QA' },
  { city: 'Riyadh', countryCode: 'SA' },
  { city: 'Jeddah', countryCode: 'SA' },
  { city: 'Dammam', countryCode: 'SA' },
  { city: 'Mumbai', countryCode: 'IN' },
  { city: 'Bengaluru', countryCode: 'IN' },
  { city: 'Bangalore', countryCode: 'IN' },
  { city: 'Delhi', countryCode: 'IN' },
  { city: 'Hyderabad', countryCode: 'IN' },
  { city: 'Chennai', countryCode: 'IN' },
  { city: 'Kolkata', countryCode: 'IN' },
  { city: 'London', countryCode: 'GB' },
  { city: 'Manchester', countryCode: 'GB' },
  { city: 'New York', countryCode: 'US' },
  { city: 'Los Angeles', countryCode: 'US' },
  { city: 'San Francisco', countryCode: 'US' },
  { city: 'Toronto', countryCode: 'CA' },
  { city: 'Vancouver', countryCode: 'CA' },
  { city: 'Sydney', countryCode: 'AU' },
  { city: 'Melbourne', countryCode: 'AU' },
  { city: 'Dunedin', countryCode: 'NZ' },
  { city: 'Dushanbe', countryCode: 'TJ' },
  { city: 'Singapore', countryCode: 'SG' },
  { city: 'Tokyo', countryCode: 'JP' },
  { city: 'Berlin', countryCode: 'DE' },
  { city: 'Paris', countryCode: 'FR' },
  { city: 'Rome', countryCode: 'IT' },
  { city: 'Kuala Lumpur', countryCode: 'MY' },
  { city: 'Bangkok', countryCode: 'TH' },
]

type Suggestion = {
  label: string
  country: string
  subtitle: string
}

export function CountrySelect({
  value,
  onChange,
}: CountrySelectProps) {
  const [query, setQuery] = useState(value || '')
  const [open, setOpen] = useState(false)
  const [activeIndex, setActiveIndex] = useState(0)
  const wrapperRef = useRef<HTMLDivElement>(null)

  useEffect(() => {
    setQuery(value || '')
  }, [value])

  useEffect(() => {
    function handleOutsideClick(event: MouseEvent) {
      if (
        wrapperRef.current &&
        !wrapperRef.current.contains(event.target as Node)
      ) {
        setOpen(false)
        setQuery(value || '')
      }
    }

    document.addEventListener('mousedown', handleOutsideClick)

    return () => {
      document.removeEventListener('mousedown', handleOutsideClick)
    }
  }, [value])

  const suggestions = useMemo(() => {
    const term = query.trim().toLowerCase()

    if (!term) return []

    const results: Suggestion[] = []

    // Countries beginning with typed letters appear first.
    for (const country of countries) {
      if (country.name.toLowerCase().startsWith(term)) {
        results.push({
          label: country.name,
          country: country.name,
          subtitle: 'Country',
        })
      }
    }

    // Then other country-name matches.
    for (const country of countries) {
      const name = country.name.toLowerCase()
      if (name.includes(term) && !name.startsWith(term)) {
        results.push({
          label: country.name,
          country: country.name,
          subtitle: 'Country',
        })
      }
    }

    // City matches are searchable and save the parent country.
    for (const alias of cityAliases) {
      if (!alias.city.toLowerCase().startsWith(term)) continue

      const country =
        countries.find(c => c.code === alias.countryCode)?.name ||
        alias.countryCode

      results.push({
        label: alias.city,
        country,
        subtitle: `City · ${country}`,
      })
    }

    // Common country abbreviations.
    const abbreviations = [
      { search: 'uae', code: 'AE' },
      { search: 'usa', code: 'US' },
      { search: 'uk', code: 'GB' },
    ]

    for (const item of abbreviations) {
      if (!item.search.startsWith(term)) continue

      const country = countries.find(c => c.code === item.code)
      if (country) {
        results.push({
          label: item.search.toUpperCase(),
          country: country.name,
          subtitle: `Country · ${country.name}`,
        })
      }
    }

    return results.slice(0, 12)
  }, [query])

  function selectCountry(country: string) {
    setQuery(country)
    onChange(country)
    setOpen(false)
    setActiveIndex(0)
  }

  return (
    <div
      ref={wrapperRef}
      className="operations-field"
      style={{
        position: 'relative',
        minWidth: 180,
      }}
    >
      <label
        htmlFor="management-country-search"
        style={{
          display: 'block',
          marginBottom: 6,
          fontWeight: 600,
        }}
      >
        Country *
      </label>

      <input
        id="management-country-search"
        type="text"
        autoComplete="off"
        placeholder="Search country or city..."
        value={query}
        onFocus={() => {
          if (query.trim() && query !== value) setOpen(true)
        }}
        onChange={event => {
          setQuery(event.target.value)
          setOpen(true)
          setActiveIndex(0)
          onChange('')
        }}
        onKeyDown={event => {
          if (!open || suggestions.length === 0) {
            if (event.key === 'Escape') setOpen(false)
            return
          }

          if (event.key === 'ArrowDown') {
            event.preventDefault()
            setActiveIndex(index =>
              Math.min(index + 1, suggestions.length - 1)
            )
          } else if (event.key === 'ArrowUp') {
            event.preventDefault()
            setActiveIndex(index => Math.max(index - 1, 0))
          } else if (event.key === 'Enter') {
            event.preventDefault()
            selectCountry(suggestions[activeIndex].country)
          } else if (event.key === 'Escape') {
            setOpen(false)
          }
        }}
        required
        role="combobox"
        aria-expanded={open && suggestions.length > 0}
        aria-autocomplete="list"
        aria-controls="management-country-suggestions"
        aria-activedescendant={
          open && suggestions.length > 0
            ? `management-country-option-${activeIndex}`
            : undefined
        }
      />

      {open && query.trim() !== '' && (
        <div
          id="management-country-suggestions"
          role="listbox"
          style={{
            position: 'absolute',
            top: '100%',
            left: 0,
            right: 0,
            zIndex: 1000,
            background: '#ffffff',
            border: '1px solid #cbd5e1',
            borderRadius: 8,
            boxShadow: '0 8px 24px rgba(0,0,0,0.12)',
            maxHeight: 250,
            overflowY: 'auto',
            marginTop: 4,
          }}
        >
          {suggestions.length > 0 ? (
            suggestions.map((item, index) => (
              <div
                key={`${item.label}-${item.country}`}
                id={`management-country-option-${index}`}
                role="option"
                aria-selected={activeIndex === index}
                onMouseDown={event => event.preventDefault()}
                onClick={() => selectCountry(item.country)}
                onMouseEnter={() => setActiveIndex(index)}
                style={{
                  padding: '9px 12px',
                  cursor: 'pointer',
                  background:
                    activeIndex === index ? '#f1dd9b5c' : '#e9ceba',
                  borderBottom: '1px solid #177bdf',
                }}
              >
                <div style={{ fontWeight: 600, color: '#173b61' }}>
                  {item.label}
                </div>
                <div style={{ fontSize: 11, color: '#64748b' }}>
                  {item.subtitle}
                </div>
              </div>
            ))
          ) : (
            <div
              style={{
                padding: 12,
                fontSize: 12,
                color: '#4b61f0',
              }}
            >
              No match found 
            </div>
          )}
        </div>
      )}
    </div>
  )
}
